<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from './PageShell.vue';import {usePage} from '../composables/usePage';import {request,download} from '../utils/request';import {go,time,checks} from '../utils/format';defineProps<{report?:boolean}>();const id=ref(0),order=ref<any>(null),media=ref<any[]>([]),reportData=ref<any>(null),video=ref('');onLoad(q=>id.value=Number(q?.id));const {loading,error,load,action}=usePage(async()=>{[order.value,media.value]=await Promise.all([request('/orders/'+id.value),request('/orders/'+id.value+'/media')]);if(order.value.status==='COMPLETED')reportData.value=await request('/orders/'+id.value+'/report')});async function open(m:any){const path=await download(id.value,m.id);if(m.kind==='PHOTO')uni.previewImage({urls:[path]});else video.value=path}
</script><template><PageShell :title="report?'喂养报告':'服务进行中'" back :loading="loading" :error="error" @retry="load"><template v-if="order"><view class="title">{{report?'今天也被好好照顾了。':'此刻，有人在认真陪它。'}}</view><view class="subtitle" style="margin-bottom:20px">{{order.pet_snapshot?.map((p:any)=>p.name).join('、')}} · {{time(order.service_start)}}</view><view class="notice">{{reportData?.status==='PENDING_AI'?'服务记录已生成。AI 图文总结尚未开放，以下为喂养师提交的原始记录。':'以下展示已提交的服务记录，可刷新获取最新进展。'}}</view><view class="card"><view class="row"><text>进门时间</text><text>{{time(order.checkin_at)}}</text></view><view class="row"><text>离门时间</text><text>{{time(order.checkout_at)}}</text></view></view><view class="section">照护清单 <text class="link" @click="load">刷新</text></view><view class="card"><view v-for="c in order.checklist" :key="c.code" class="menu-item"><view><view>{{c.completed?'✓':'○'}} {{checks[c.code]}}</view><text class="muted">{{c.notes}}</text></view><text class="link">{{c.quantity||''}} {{c.unit==='MINUTE'?'分钟':c.unit||''}}</text></view></view><view class="section">现场照片与录像</view><view class="card"><view v-for="m in media" :key="m.id" class="menu-item" @click="action(()=>open(m),'')"><text>{{m.kind==='PHOTO'?'▧ 现场照片':'▷ 服务录像'}}</text><text class="link">查看 ›</text></view><text v-if="!media.length" class="muted">喂养师尚未上传媒体</text><text v-else class="muted">媒体在有效期内仅对订单相关人员开放。</text></view><video v-if="video" :src="video" controls style="width:100%"/><button class="secondary" @click="go('owner/service?orderId='+id)">进入专属服务群</button><button v-if="order.status==='COMPLETED'&&!order.review" class="primary" style="margin-top:12px" @click="go('owner/review?id='+id)">评价喂养师</button></template></PageShell></template>
